SELECT  FROM delivery_risk r
JOIN delivery d ON d.id = r.delivery_id
WHERE d.buyer_tenant_id = #{tenantId} AND r.is_deleted = 0

    AND r.risk_status = #{riskStatus}


    AND r.risk_level = #{riskLevel}

ORDER BY r.create_time DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM delivery_risk r
